import json
from playwright.sync_api import sync_playwright

def scrape_papers(venue_url, conference_name):
    with sync_playwright() as p:
        browser = p.chromium.launch(headless=True)
        page = browser.new_page()

        # Load OpenReview search page
        print(f"Navigating to {venue_url}...")
        page.goto(venue_url, wait_until='domcontentloaded', timeout=60000)

        # Wait for content to load
        page.wait_for_timeout(5000)

        # Try to scroll and wait for papers to load
        page.evaluate('window.scrollTo(0, document.body.scrollHeight)')
        page.wait_for_timeout(3000)

        # Check if we got any content
        content = page.content()
        if 'table-row' not in content.lower() and 'paper' not in content.lower():
            # Try the accepted submission page directly
            print("Main search didn't show papers, trying accepted submission page...")

        # Extract paper table data
        papers = page.evaluate('''
            () => {
                const rows = document.querySelectorAll('table tr');
                const results = [];
                rows.forEach(row => {
                    const cells = row.querySelectorAll('td');
                    if (cells.length >= 3) {
                        const tds = Array.from(cells).map(c => c.textContent.trim());
                        if (tds.length > 0 && tds.some(t => t.length > 10)) {
                            results.push(tds);
                        }
                    }
                });
                return results;
            }
        ''')

        print(f"Found {len(papers)} rows for {conference_name}")

        # Show a sample
        if papers:
            print(f"Sample: {papers[0]}")

        browser.close()
        return papers

# Try ICML 2024 first
papers = scrape_papers('https://openreview.net/group?id=ICML.cc/2024/Conference', 'ICML 2024')
print(f"\nTotal ICML 2024 papers found: {len(papers)}")
