def intercept_api(page):
    api_data = {}

    def handle_response(response):
        url = response.url
        if '/api/notes' in url or '/api/references' in url or '/search' in url:
            try:
                body = response.json()
                api_data[url] = body
            except:
                pass

    page.on('response', handle_response)
    return api_data

