        print("Waiting for turnstile...")
        for i in range(20):
            page.wait_for_timeout(1000)
            # Check if we've passed the verification
            body = page.evaluate('document.body.innerText.substring(0, 500)')
            if 'Verifying' not in body and len(body) > 100:
                print(f"Passed verification after {i}s. Body starts: {body[:200]}")
                break
        else:
            print("Still on verification page after 20s")

        # Now use fetch from within the browser context
        page_content = page.evaluate('''
            () => {
                return {
                    title: document.title,
                    url: window.location.href,
                    bodyText: document.body.innerText.substring(0, 2000)
                };
            }
        ''')
        print(f"Page: {json.dumps(page_content, indent=2)[:500]}")

        # Try fetching notes from OpenReview API from browser context
        try:
