                async () => {
                    try {
                        const resp = await fetch('https://api.openreview.net/notes?invitation=ICML.cc%2F2024%2FConference%2F-%2FAccepted_Submission&limit=5&content.venue=ICML%202024');
                        return {status: resp.status, data: await resp.text().then(t => { try { return JSON.parse(t); } catch(e) { return t; } })};
                    } catch(e) {
                        return {error: e.message};
                    }
                }
            ''')
            print(f"\nAPI response: {json.dumps(notes, indent=2)[:2000]}")
        except Exception as e:
            print(f"Fetch error: {e}")

        browser.close()

run()
