import json
from playwright.sync_api import sync_playwright
import re

def run():
    with sync_playwright() as p:
        browser = p.chromium.launch(headless=True)
        context = browser.new_context(
            user_agent='Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/125.0.0.0 Safari/537.36',
            viewport={'width': 1920, 'height': 1080}
        )
        context.add_init_script('Object.defineProperty(navigator, "webdriver", {get: () => false})')
        page = context.new_page()

        # Capture all fetch/XHR responses
        api_responses = {}

        def handle_response(response):
            url = response.url
            ct = response.headers.get('content-type', '')
            if ('api/openreview.net' in url or 'openreview.net/api' in url) and 'application/json' in ct:
                try:
                    body = response.json()
                    api_responses[url] = body
                    print(f"Captured: {url[:120]}")
                except:
                    pass

        page.on('response', handle_response)

        # Navigate to search page with proper query format
        page.goto('https://openreview.net/search?query=ICML+2024&content=accepted', 
                  wait_until='domcontentloaded', timeout=60000)

        # Wait for turnstile to solve
        print("Waiting for turnstile...")
        for i in range(30):
            page.wait_for_timeout(1000)
            body = page.evaluate('document.body.innerText.substring(0, 500)')
            if 'Verifying' not in body and ('Error' not in body or 'Missing search' in body):
                title = page.evaluate('document.title')
                if title == 'Search | OpenReview':
                    print(f"Search page loaded after {i}s")
                    break
        else:
            print("Still on verification")
            browser.close()
            return

        # Now check what the page content looks like
        body_text = page.evaluate('document.body.innerText.substring(0, 5000)')
        print(f"\nPage body (5000 chars):\n{body_text[:2000]}")

        # Check if there are paper links
        paper_links = page.evaluate('''
            () => {
                const links = Array.from(document.querySelectorAll('a')).filter(a => 
                    a.href.includes('pmlr') || a.href.includes('openreview.net/forum')
                );
                return links.slice(0, 10).map(a => ({text: a.textContent.trim(), href: a.href}));
            }
        ''')
        print(f"\nPaper links: {len(paper_links)}")
        for link in paper_links:
            print(f"  {link['text'][:60]}... -> {link['href']}")

        # If page didn't load papers, try clicking search button
        search_btn = page.query_selector('button[type="submit"]')
        if not search_btn:
            # Look for search input and simulate search
            search_input = page.query_selector('input[name="q"], input[type="search"], input[placeholder*="search"]')
            if search_input:
                print("Found search input, submitting...")
                search_input.fill('ICML 2024 accepted')
                page.keyboard.press('Enter')
                page.wait_for_timeout(5000)

        # Check API responses captured
        print(f"\n=== API Responses Captured ===")
        for url, data in api_responses.items():
            print(f"URL: {url[:150]}")
            if isinstance(data, dict):
                print(f"  Keys: {list(data.keys())[:10]}")
                for k, v in list(data.items())[:5]:
                    if isinstance(v, list):
                        print(f"  {k}: [{len(v)} items]")
                        if v:
                            print(f"    [0]: {list(v[0].keys())[:10] if isinstance(v[0], dict) else v[0]}")
                    elif isinstance(v, (str, int, float)):
                        print(f"  {k}: {v}")
            elif isinstance(data, list):
                print(f"  List of {len(data)} items")
                if data:
                    print(f"    [0]: {list(data[0].keys())[:10] if isinstance(data[0], dict) else data[0]}")

        browser.close()

run()
